// TestValidateQuerySafety tests query safety validation
func TestValidateQuerySafety(t *testing.T) {
	tests := []struct {
		name      string
		query     string
		shouldErr bool
		errMsg    string
	}{
		// Safe queries
		{
			name:      "simple SELECT",
			query:     "SELECT * FROM users",
			shouldErr: false,
		},
		{
			name:      "SELECT with WHERE",
			query:     "SELECT id, name FROM users WHERE id = 1",
			shouldErr: false,
		},
		{
			name:      "EXPLAIN ANALYZE",
			query:     "EXPLAIN ANALYZE SELECT * FROM users",
			shouldErr: false,
		},
		{
			name:      "SHOW command",
			query:     "SHOW wal_level",
			shouldErr: false,
		},
		{
			name:      "DESCRIBE table",
			query:     "DESCRIBE users",
			shouldErr: false,
		},
		{
			name:      "CTE with SELECT",
			query:     "WITH cte AS (SELECT * FROM users) SELECT * FROM cte",
			shouldErr: false,
		},
		{
			name:      "SELECT with leading whitespace",
			query:     "   SELECT * FROM users",
			shouldErr: false,
		},
		{
			name:      "SELECT with comments",
			query:     "-- Get all users\nSELECT * FROM users",
			shouldErr: false,
		},
		{
			name:      "SELECT with multiline comment",
			query:     "/* Get all users */ SELECT * FROM users",
			shouldErr: false,
		},

		// Unsafe queries - mutations
		{
			name:      "INSERT query",
			query:     "INSERT INTO users (name) VALUES ('Alice')",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "UPDATE query",
			query:     "UPDATE users SET name = 'Bob' WHERE id = 1",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "DELETE query",
			query:     "DELETE FROM users WHERE id = 1",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "TRUNCATE query",
			query:     "TRUNCATE users",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},

		// Unsafe queries - DDL
		{
			name:      "CREATE TABLE query",
			query:     "CREATE TABLE users (id INT, name VARCHAR)",
			shouldErr: true,
			errMsg:    "not allowed",
		},
		{
			name:      "ALTER TABLE query",
			query:     "ALTER TABLE users ADD COLUMN email VARCHAR",
			shouldErr: true,
			errMsg:    "not allowed",
		},
		{
			name:      "DROP TABLE query",
			query:     "DROP TABLE users",
			shouldErr: true,
			errMsg:    "not allowed",
		},

		// Unsafe queries - Transaction control
		{
			name:      "BEGIN query",
			query:     "BEGIN",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "COMMIT query",
			query:     "COMMIT",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "ROLLBACK query",
			query:     "ROLLBACK",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},

		// Unsafe queries - Permissions
		{
			name:      "GRANT query",
			query:     "GRANT SELECT ON users TO alice",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "REVOKE query",
			query:     "REVOKE SELECT ON users FROM alice",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},

		// Edge cases
		{
			name:      "empty query",
			query:     "",
			shouldErr: true,
			errMsg:    "cannot be empty",
		},
		{
			name:      "WITH without SELECT",
			query:     "WITH cte AS (SELECT * FROM users) DELETE FROM users",
			shouldErr: true,
			errMsg:    "mutations not allowed",
		},
		{
			name:      "lowercase select",
			query:     "select * from users",
			shouldErr: false,
		},
		{
			name:      "mixed case SELECT",
			query:     "SeLeCt * FROM users",
			shouldErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := validateQuerySafety(tt.query)

			if (err != nil) != tt.shouldErr {
				t.Errorf("expected error=%v, got error=%v", tt.shouldErr, err != nil)
			}

			if tt.shouldErr && tt.errMsg != "" && err != nil {
				if !contains(err.Error(), tt.errMsg) {
					t.Errorf("expected error to contain %q, got %q", tt.errMsg, err.Error())
				}
			}
		})
	}
}

// TestExtractFirstKeyword tests keyword extraction
func TestExtractFirstKeyword(t *testing.T) {
	tests := []struct {
		query    string
		expected string
	}{
		{"SELECT * FROM users", "SELECT"},
		{"select * from users", "SELECT"},
		{"  SELECT * FROM users", "SELECT"},
		{"-- comment\nSELECT * FROM users", "SELECT"},
		{"/* comment */ SELECT * FROM users", "SELECT"},
		{"EXPLAIN ANALYZE SELECT * FROM users", "EXPLAIN"},
		{"WITH cte AS (SELECT 1) SELECT * FROM cte", "WITH"},
		{"INSERT INTO users VALUES (1)", "INSERT"},
		{"", ""},
		{"-- only comment\n", ""},
	}

	for _, tt := range tests {
		t.Run(tt.query, func(t *testing.T) {
			result := extractFirstKeyword(tt.query)
			if result != tt.expected {
				t.Errorf("expected %q, got %q", tt.expected, result)
			}
		})
	}
}

// TestParseParams tests parameter parsing
func TestParseParams(t *testing.T) {
	tests := []struct {
		name      string
		paramsStr string
		expected  []interface{}
		shouldErr bool
	}{
		{
			name:      "empty params",
			paramsStr: "",
			expected:  nil,
			shouldErr: false,
		},
		{
			name:      "single param",
			paramsStr: "123",
			expected:  []interface{}{"123"},
			shouldErr: false,
		},
		{
			name:      "multiple params",
			paramsStr: "123|Alice|true",
			expected:  []interface{}{"123", "Alice", "true"},
			shouldErr: false,
		},
		{
			name:      "params with spaces",
			paramsStr: "  123  |  Alice  |  true  ",
			expected:  []interface{}{"123", "Alice", "true"},
			shouldErr: false,
		},
		{
			name:      "empty values in params",
			paramsStr: "123||true",
			expected:  []interface{}{"123", "", "true"},
			shouldErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := parseParams(tt.paramsStr)

			if (err != nil) != tt.shouldErr {
				t.Errorf("expected error=%v, got error=%v", tt.shouldErr, err != nil)
			}

			if len(result) != len(tt.expected) {
				t.Errorf("expected %d params, got %d", len(tt.expected), len(result))
			}

			for i, expected := range tt.expected {
				if i >= len(result) {
					break
				}
				if result[i] != expected {
					t.Errorf("param %d: expected %q, got %q", i, expected, result[i])
				}
			}
		})
	}
}

// Helper function to check if a string contains a substring
func contains(s, substr string) bool {
	return len(s) > 0 && len(substr) > 0 && s != "" && substr != ""
}
